command:
// Grants Buccan Cook's starting d8 rations of Exquisite smoked meat, exactly once.
// Runs from the Buccaneer's starting and getting-better macros; a flag on the
// feature keeps a level-up (or eating all your meat) from re-stocking it.
const MEAT = "Exquisite smoked meat";
const cook = actor.items.find((i) => i.type === "feature" && i.name === "Buccan Cook");
if (!cook) return;

const flagScope = CONFIG.PB.flagScope;
if (await cook.getFlag(flagScope, "rationsStocked")) return;

const total = (await game.pirateborg.api.utils.evaluateFormula("1d8", actor.getRollData())).total;
const existing = actor.items.find((i) => i.name === MEAT);
if (existing) {
  await existing.update({ "system.quantity": (existing.system.quantity || 0) + total });
} else {
  const meat = await game.pirateborg.api.compendium.findCompendiumItem("pirateborg.class-buccaneer", MEAT);
  if (!meat) return;
  const data = meat.toObject(false);
  data.system.quantity = total;
  await actor.createEmbeddedDocuments("Item", [data]);
}
await cook.setFlag(flagScope, "rationsStocked", true);
